def eulerian_iterative(n, m):
    """
    Computes the Eulerian number a(n, m) iteratively.
    """
    if n == 0:
        return int(m == 0)
    eulerian = [0] * (n + 1)
    eulerian[0] = 1
    for i in range(1, n + 1):
