def find_solution(a, b, n):
    def gcd(x, y):
        """Helper to compute greatest common divisor."""
        while y:
            x, y = y, x % y
        return x

    def extended_gcd(x, y):
        """Helper to compute the coefficients used in Bezout's identity."""
        if x == 0:
            return y, 0, 1
        else:
            g, y1, x1 = extended_gcd(y % x, x)
            y = y1
            x = x1 - (y // x) * x1
            return g, x, y

    g = gcd(a, b)
    if n % g != 0:
        return None
    else:
        d, x, y = extended_gcd(a, b)
        k = n // d
        return (k * x, k * y)

