def get_median(list1, list2):
    total_length = len(list1)
    mid_index = total_length // 2

    # Helper function to find the k-th smallest element in two sorted arrays
    def find_kth_smallest(left, right, k):
        if not left: return right[k]
        if not right: return left[k]
        if k == 0: return min(left[0], right[0])

        mid_left = min(k // 2, len(left) - 1)
        mid_right = min(k // 2, len(right) - 1)

        if left[mid_left] <= right[mid_right]:
            return find_kth_smallest(left[mid_left + 1:], right, k - mid_left - 1)
        else:
            return find_kth_smallest(left, right[mid_right + 1:], k - mid_right - 1)

    kth_smallest = find_kth_smallest(list1, list2, mid_index)
    if total_length % 2 == 1:
        return kth_smallest
    else:
